from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')

old_boundary="function earthlineBoundaryPoint16539(a,b,g,aInside){let lo=0,hi=1;for(let i=0;i<22;i++){const mid=(lo+hi)/2,v=earthlinePointInJurisdiction16539(earthlineInterpolate16539(a,b,mid),g);if(v===aInside)lo=mid;else hi=mid;}return earthlineInterpolate16539(a,b,(lo+hi)/2);}"
new_boundary="function earthlineBoundaryPoint16539(a,b,g,aInside){let insideT=aInside?0:1,outsideT=aInside?1:0;for(let i=0;i<26;i++){const mid=(insideT+outsideT)/2,v=earthlinePointInJurisdiction16539(earthlineInterpolate16539(a,b,mid),g);if(v)insideT=mid;else outsideT=mid;}return earthlineInterpolate16539(a,b,insideT);}"
if s.count(old_boundary)!=1:
    raise SystemExit(f'expected exactly one boundary helper, found {s.count(old_boundary)}')
s=s.replace(old_boundary,new_boundary,1)

old_fc="function earthlineClipFeatureCollection16539(fc,g){\n    const out=[];for(const feature of (fc&&fc.features||[])){if(!feature||!feature.geometry)continue;const geom=feature.geometry,props=Object.assign({},feature.properties||{});if(geom.type==='Point'){if(earthlinePointInJurisdiction16539(geom.coordinates,g))out.push({type:'Feature',properties:props,geometry:JSON.parse(JSON.stringify(geom))});continue;}const lines=geom.type==='LineString'?[geom.coordinates]:geom.type==='MultiLineString'?(geom.coordinates||[]):[];for(const line of lines)for(const run of earthlineClipLine16539(line,g))out.push({type:'Feature',properties:Object.assign({},props,{jurisdiction_boundary_screened:true}),geometry:{type:'LineString',coordinates:run}});}return {type:'FeatureCollection',features:out};\n  }"
new_fc="function earthlineClipFeatureCollection16539(fc,g){\n    const out=[];for(const feature of (fc&&fc.features||[])){if(!feature||!feature.geometry)continue;const geom=feature.geometry,props=Object.assign({},feature.properties||{});if(geom.type==='Point'){if(earthlinePointInJurisdiction16539(geom.coordinates,g))out.push({type:'Feature',properties:props,geometry:JSON.parse(JSON.stringify(geom))});continue;}const lines=geom.type==='LineString'?[geom.coordinates]:geom.type==='MultiLineString'?(geom.coordinates||[]):[];for(const line of lines)for(const run of earthlineClipLine16539(line,g)){const safe=run.filter(p=>earthlinePointInJurisdiction16539(p,g));if(safe.length>=2)out.push({type:'Feature',properties:Object.assign({},props,{jurisdiction_boundary_screened:true}),geometry:{type:'LineString',coordinates:safe}});}}return {type:'FeatureCollection',features:out};\n  }\n  function earthlineOutsideCoordinateCount16539(fc,g){let outside=0;for(const f of (fc&&fc.features||[])){const geom=f&&f.geometry;if(!geom)continue;if(geom.type==='Point'){if(!earthlinePointInJurisdiction16539(geom.coordinates,g))outside++;continue;}const lines=geom.type==='LineString'?[geom.coordinates]:geom.type==='MultiLineString'?(geom.coordinates||[]):[];for(const line of lines)for(const p of (line||[]))if(earthlineFinitePoint16539(p)&&!earthlinePointInJurisdiction16539(p,g))outside++;}return outside;}"
if s.count(old_fc)!=1:
    raise SystemExit(f'expected exactly one feature clipper, found {s.count(old_fc)}')
s=s.replace(old_fc,new_fc,1)

old_prod="const after={contours:contours.features.length,flows:flows.features.length,swales:swales.features.length};\n    const audit={build:'EARTHLINE 16539',runToken:payload.runToken||null,query:String(payload.query||''),placeType:boundary.placeType,capability:boundary.capability,source:boundary.source,sourceTier:boundary.sourceTier,sourceVintage:boundary.sourceVintage||null,before,after,removed:{contours:Math.max(0,before.contours-after.contours),flows:Math.max(0,before.flows-after.flows),swales:Math.max(0,before.swales-after.swales)},rule:'hydrology computed continuously on the full DEM envelope; only published Regional products are clipped to the selected administrative polygon',at:new Date().toISOString()};"
new_prod="const after={contours:contours.features.length,flows:flows.features.length,swales:swales.features.length};\n    const outsideAfterClip={contours:earthlineOutsideCoordinateCount16539(contours,g),flows:earthlineOutsideCoordinateCount16539(flows,g),swales:earthlineOutsideCoordinateCount16539(swales,g)};\n    if(outsideAfterClip.contours||outsideAfterClip.flows||outsideAfterClip.swales)throw new Error('administrative boundary containment invariant failed');\n    const audit={build:'EARTHLINE 16539',runToken:payload.runToken||null,query:String(payload.query||''),placeType:boundary.placeType,capability:boundary.capability,source:boundary.source,sourceTier:boundary.sourceTier,sourceVintage:boundary.sourceVintage||null,before,after,outsideAfterClip,removed:{contours:Math.max(0,before.contours-after.contours),flows:Math.max(0,before.flows-after.flows),swales:Math.max(0,before.swales-after.swales)},rule:'hydrology computed continuously on the full DEM envelope; only published Regional products are clipped to the selected administrative polygon',at:new Date().toISOString()};"
if s.count(old_prod)!=1:
    raise SystemExit(f'expected exactly one product audit block, found {s.count(old_prod)}')
s=s.replace(old_prod,new_prod,1)

p.write_text(s,encoding='utf-8')
print('repaired shared administrative line clipping: inside-side intersections + fail-closed containment invariant')
